/** Insert the sprite once per document. Safe to call many times. */
export function mountOrnaments(doc = document) {
    if (!doc.body || doc.getElementById(ORNAMENT_SPRITE_ID)) {
        return;
    }
    const svg = doc.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("id", ORNAMENT_SPRITE_ID);
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("width", "0");
    svg.setAttribute("height", "0");
    svg.style.position = "absolute";
    svg.innerHTML = `<defs>${ORNAMENT_DEFS}</defs>`;
    doc.body.prepend(svg);
}

